async def act(page):
    """
    From the current "New Rule / Magento Admin" page, complete the Actions tab to set a fixed $15 discount
    for all customer groups, then save the rule.

    Notes about knowledge-base functions: none are available in the provided environment, so none are used.
    """
    # Wait for the page to be ready
    await page.wait_for_load_state("domcontentloaded")

    # Click the Actions tab so we can set the discount and action
    try:
        actions_tab = page.get_by_role("link", name="Actions")
        if await actions_tab.count() > 0:
            await actions_tab.first.click()
            # Allow the tab content to render
            await page.wait_for_timeout(500)
    except Exception:
        # If clicking Actions fails, continue; subsequent selectors will attempt to find the controls anyway
        pass

    # Ensure all customer groups are selected (so it applies to all customers)
    try:
        customer_groups = page.get_by_role("listbox", name="Customer Groups *")
        if await customer_groups.count() > 0:
            options = [
                {"label": "NOT LOGGED IN"},
                {"label": "General"},
                {"label": "Wholesale"},
                {"label": "VIP Member"},
                {"label": "Private Sales Member"},
            ]
            # select_option accepts a list of option dicts
            await customer_groups.first.select_option(options)
            await page.wait_for_timeout(200)
    except Exception:
        # fallback: try any listbox whose name contains 'Customer Groups'
        try:
            all_listboxes = page.get_by_role("listbox")
            count = await all_listboxes.count()
            for i in range(count):
                lb = all_listboxes.nth(i)
                try:
                    # attempt to read accessible name by interacting; if it looks like customer groups, select all options
                    name = await lb.get_attribute("name")
                except Exception:
                    name = None
                try:
                    # best-effort select all known labels
                    await lb.select_option([{"label": "NOT LOGGED IN"}, {"label": "General"}, {"label": "Wholesale"}, {"label": "VIP Member"}, {"label": "Private Sales Member"}])
                except Exception:
                    continue
        except Exception:
            pass

    # Set the rule Action (Apply) to "Fixed amount discount"
    try:
        apply_combo = page.get_by_role("combobox", name="Apply")
        if await apply_combo.count() > 0:
            await apply_combo.first.select_option({"label": "Fixed amount discount"})
            await page.wait_for_timeout(200)
    except Exception:
        # try alternate combobox name
        try:
            apply_combo = page.get_by_role("combobox", name="Action")
            if await apply_combo.count() > 0:
                await apply_combo.first.select_option({"label": "Fixed amount discount"})
                await page.wait_for_timeout(200)
        except Exception:
            pass

    # Fill the Discount Amount with 15 (try spinbutton then textbox)
    filled_discount = False
    try:
        spin = page.get_by_role("spinbutton", name="Discount Amount")
        if await spin.count() > 0:
            await spin.first.fill("15")
            filled_discount = True
    except Exception:
        pass

    if not filled_discount:
        try:
            txt = page.get_by_role("textbox", name="Discount Amount")
            if await txt.count() > 0:
                await txt.first.fill("15")
                filled_discount = True
        except Exception:
            pass

    # As an additional fallback, try a generic textbox labeled 'Discount'
    if not filled_discount:
        try:
            txt2 = page.get_by_role("textbox", name="Discount")
            if await txt2.count() > 0:
                await txt2.first.fill("15")
                filled_discount = True
        except Exception:
            pass

    # Small wait for dynamic updates
    await page.wait_for_timeout(300)

    # Finally, click Save (this will navigate away) - make this the last action
    try:
        save_btn = page.get_by_role("button", name="Save")
        if await save_btn.count() > 0:
            await save_btn.first.click()
            return
    except Exception:
        pass

    # fallback: try the "Save and Continue Edit" if plain Save not found
    try:
        save_continue = page.get_by_role("button", name="Save and Continue Edit")
        if await save_continue.count() > 0:
            await save_continue.first.click()
            return
    except Exception:
        pass

    # If no save control found, end here
    return

